#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^#([0-9]+)\s*([a-zA-Z]+)$)");
    std::smatch match;
    while (std::regex_search(html, match, re)) {
        html = match[1] + "<h" + std::stoi(match[2]) + ">" + match[3] + "</h" + std::stoi(match[2]) + ">";
    }
    return html;
}
```

